// Generated by scripts/generate-story-sources.mjs. Edit the showcase demos instead.
export const examples: Record<string, string> = {
  "Layout/Accordion": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from \"@/components/ui/accordion\";\nexport function Example() {\n    return (<DemoCard title=\"Accordion\" description=\"Progressive disclosure, with keyboard navigation.\" full>\n        <Accordion type=\"single\" collapsible defaultValue=\"one\">\n          <AccordionItem value=\"one\">\n            <AccordionTrigger>\n              What makes this a reusable design system?\n            </AccordionTrigger>\n            <AccordionContent>\n              Every component uses centralized semantic tokens for colors,\n              spacing, borders, and interaction states. Pages use the same\n              reusable building blocks.\n            </AccordionContent>\n          </AccordionItem>\n          <AccordionItem value=\"two\">\n            <AccordionTrigger>\n              How do I customize the theme?\n            </AccordionTrigger>\n            <AccordionContent>\n              Update the semantic variables in theme.css. Shared values apply\n              consistently to overlays, charts, forms, and navigation.\n            </AccordionContent>\n          </AccordionItem>\n          <AccordionItem value=\"three\">\n            <AccordionTrigger>\n              Can I use this for a data-heavy application?\n            </AccordionTrigger>\n            <AccordionContent>\n              The boxed shell, compact type scale, accessible controls, and\n              responsive tables are designed for everyday business workflows.\n            </AccordionContent>\n          </AccordionItem>\n        </Accordion>\n      </DemoCard>);\n}\n",
  "Overlays/Alert Dialog": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { AlertDialog, AlertDialogTrigger, AlertDialogContent, AlertDialogHeader, AlertDialogTitle, AlertDialogDescription, AlertDialogFooter, AlertDialogCancel, AlertDialogAction } from \"@/components/ui/alert-dialog\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Alert dialog\" description=\"Deliberate confirmation for destructive actions.\">\n        <div className=\"demo-stack\">\n          <p className=\"text-sm text-muted-foreground\">\n            Clear language, a safe cancel action, and a distinct destructive\n            button.\n          </p>\n          <AlertDialog>\n            <AlertDialogTrigger asChild>\n              <Button variant=\"destructive\">Delete draft</Button>\n            </AlertDialogTrigger>\n            <AlertDialogContent>\n              <AlertDialogHeader>\n                <AlertDialogTitle>Delete this draft?</AlertDialogTitle>\n                <AlertDialogDescription>\n                  This removes the example draft from this preview. Your saved\n                  invoice remains available.\n                </AlertDialogDescription>\n              </AlertDialogHeader>\n              <AlertDialogFooter>\n                <AlertDialogCancel>Keep draft</AlertDialogCancel>\n                <AlertDialogAction className=\"bg-destructive text-white hover:bg-destructive/90\" onClick={() => toast.success(\"Example draft deleted\")}>\n                  Delete draft\n                </AlertDialogAction>\n              </AlertDialogFooter>\n            </AlertDialogContent>\n          </AlertDialog>\n        </div>\n      </DemoCard>);\n}\n",
  "Feedback/Alert": "import { Info, TriangleAlert, CircleCheck } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Alert, AlertTitle, AlertDescription } from \"@/components/ui/alert\";\nexport function Example() {\n    return (<DemoCard title=\"Alerts\" description=\"Useful context with clear visual priority.\" full>\n        <div className=\"demo-stack\">\n          <Alert>\n            <Info />\n            <AlertTitle>A little context goes a long way</AlertTitle>\n            <AlertDescription>\n              Your draft is saved locally on this device.\n            </AlertDescription>\n          </Alert>\n          <Alert className=\"bg-[var(--success-soft)] text-[var(--success)] border-transparent\">\n            <CircleCheck />\n            <AlertTitle>Invoice saved successfully</AlertTitle>\n            <AlertDescription className=\"text-[var(--success)]\">\n              Everything is ready for your review.\n            </AlertDescription>\n          </Alert>\n          <Alert className=\"bg-[var(--warning-soft)] text-[var(--warning)] border-transparent\">\n            <TriangleAlert />\n            <AlertTitle>Payment due soon</AlertTitle>\n            <AlertDescription className=\"text-[var(--warning)]\">\n              This invoice is due in three days.\n            </AlertDescription>\n          </Alert>\n          <Alert variant=\"destructive\">\n            <TriangleAlert />\n            <AlertTitle>Something needs your attention</AlertTitle>\n            <AlertDescription>\n              Check the email address and try again.\n            </AlertDescription>\n          </Alert>\n        </div>\n      </DemoCard>);\n}\n",
  "Layout/Aspect Ratio": "import { Layers } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Separator } from \"@/components/ui/separator\";\nimport { AspectRatio } from \"@/components/ui/aspect-ratio\";\nexport function Example() {\n    return (<DemoCard title=\"Aspect ratio & surfaces\" description=\"Consistent media framing without layout shifts.\">\n        <AspectRatio ratio={16 / 9} className=\"rounded-md bg-accent border flex items-center justify-center\">\n          <div className=\"text-center text-primary\">\n            <Layers size={40} className=\"mx-auto mb-3\"/>\n            <strong className=\"text-sm\">Room for your next idea</strong>\n            <p className=\"text-sm mt-1\">16 : 9 aspect ratio</p>\n          </div>\n        </AspectRatio>\n        <Separator className=\"my-4\"/>\n        <div className=\"demo-row\">\n          <span className=\"text-sm\">Border radius: 6px</span>\n          <Separator orientation=\"vertical\" className=\"h-4\"/>\n          <span className=\"text-sm text-muted-foreground\">\n            Subtle card shadow\n          </span>\n        </div>\n      </DemoCard>);\n}\n",
  "Data/Avatar": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Avatar, AvatarImage, AvatarFallback } from \"@/components/ui/avatar\";\nexport function Example() {\n    return (<DemoCard title=\"Avatars\" description=\"Images, meaningful initials, and fallback states.\">\n        <div className=\"demo-row\">\n          <Avatar className=\"size-12\">\n            <AvatarFallback className=\"bg-accent text-primary\">\n              AM\n            </AvatarFallback>\n          </Avatar>\n          <Avatar>\n            <AvatarFallback>JL</AvatarFallback>\n          </Avatar>\n          <Avatar className=\"size-8\">\n            <AvatarImage src=\"/missing-avatar.png\" alt=\"Sam Lee\"/>\n            <AvatarFallback>SL</AvatarFallback>\n          </Avatar>\n          <div className=\"flex -space-x-2\">\n            <Avatar className=\"border-2 border-card\">\n              <AvatarFallback>AM</AvatarFallback>\n            </Avatar>\n            <Avatar className=\"border-2 border-card\">\n              <AvatarFallback>JL</AvatarFallback>\n            </Avatar>\n            <Avatar className=\"border-2 border-card\">\n              <AvatarFallback>+4</AvatarFallback>\n            </Avatar>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Actions/Button Group": "import { ChevronDown } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { ButtonGroup, ButtonGroupSeparator } from \"@/components/ui/button-group\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Button group\" description=\"Related actions belong together.\">\n        <div className=\"demo-stack\">\n          <ButtonGroup>\n            <Button variant=\"outline\" onClick={() => toast(\"Previous selected\")}>\n              Previous\n            </Button>\n            <Button variant=\"outline\" onClick={() => toast(\"Next selected\")}>\n              Next\n            </Button>\n          </ButtonGroup>\n          <ButtonGroup>\n            <Button onClick={() => toast.success(\"Invoice saved\")}>\n              Save document\n            </Button>\n            <ButtonGroupSeparator />\n            <Button size=\"icon\" aria-label=\"More save actions\" onClick={() => toast(\"Choose a save action for your document\")}>\n              <ChevronDown />\n            </Button>\n          </ButtonGroup>\n        </div>\n      </DemoCard>);\n}\n",
  "Forms/Calendar": "import { useState } from \"react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Calendar } from \"@/components/ui/calendar\";\nimport { DatePicker } from \"@/components/ui/date-picker\";\nimport { Field, FieldLabel, FieldDescription } from \"@/components/ui/field\";\nexport function Example() {\n    const [date, setDate] = useState<Date | undefined>(new Date(2026, 9, 8)), [volume, setVolume] = useState([65]), [show, setShow] = useState(false);\n    return (<DemoCard title=\"Calendar & date picker\" description=\"A consistent calendar for scheduling and invoices.\">\n        <div className=\"flex flex-wrap gap-6\">\n          <Calendar mode=\"single\" selected={date} onSelect={setDate} defaultMonth={new Date(2026, 9, 1)} className=\"border rounded-md\"/>\n          <div className=\"flex-1 min-w-40\">\n            <Field>\n              <FieldLabel htmlFor=\"showcase-date\">Selected date</FieldLabel>\n              <DatePicker id=\"showcase-date\" value={date} onChange={setDate}/>\n              <FieldDescription>\n                Click to choose a different date.\n              </FieldDescription>\n            </Field>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Layout/Card": "import { ArrowRight, Plus } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from \"@/components/ui/card\";\nimport { Badge } from \"@/components/ui/badge\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Content card\" description=\"Composable headers, bodies, and footers.\">\n        <Card>\n          <CardHeader>\n            <Badge variant=\"secondary\" className=\"w-fit mb-2\">\n              Workspace\n            </Badge>\n            <CardTitle>Your next project starts here</CardTitle>\n            <CardDescription>\n              Bring your team, ideas, and work together.\n            </CardDescription>\n          </CardHeader>\n          <CardContent>\n            <p className=\"text-sm text-muted-foreground\">\n              A flexible foundation for everything you want to build. Start with\n              a template or a blank canvas.\n            </p>\n          </CardContent>\n          <CardFooter className=\"gap-2\">\n            <Button onClick={() => toast.success(\"New project created\")}>\n              <Plus />\n              Create project\n            </Button>\n            <Button variant=\"ghost\" onClick={() => toast(\"Invite teammates from your workspace settings\")}>\n              Learn more\n              <ArrowRight />\n            </Button>\n          </CardFooter>\n        </Card>\n      </DemoCard>);\n}\n",
  "Forms/Combobox": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Field, FieldLabel } from \"@/components/ui/field\";\nimport { Combobox, ComboboxInput, ComboboxContent, ComboboxList, ComboboxItem, ComboboxEmpty } from \"@/components/ui/combobox\";\nexport function Example() {\n    return (<DemoCard title=\"Searchable combobox\" description=\"Search frameworks and select a matching option.\">\n          <Field>\n            <FieldLabel>Searchable framework</FieldLabel>\n            <Combobox items={[\"React\", \"Vue\", \"Svelte\", \"Angular\", \"Solid\"]}>\n              <ComboboxInput placeholder=\"Select framework\" aria-label=\"Framework\"/>\n              <ComboboxContent>\n                <ComboboxEmpty>No framework found.</ComboboxEmpty>\n                <ComboboxList>\n                  {(item: string) => (<ComboboxItem key={item} value={item}>\n                      {item}\n                    </ComboboxItem>)}\n                </ComboboxList>\n              </ComboboxContent>\n            </Combobox>\n          </Field>\n      </DemoCard>);\n}\n",
  "Data/Data Table": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { DataTable, type InvoiceRow } from \"@/components/ui/data-table\";\nconst rows: InvoiceRow[] = [\n    {\n        id: \"INV-0042\",\n        customer: \"Acme Corporation\",\n        email: \"billing@acme.com\",\n        date: \"Oct 08, 2026\",\n        amount: 3561.6,\n        status: \"Draft\",\n    },\n    {\n        id: \"INV-0041\",\n        customer: \"Linear Studio\",\n        email: \"hello@linear.studio\",\n        date: \"Oct 06, 2026\",\n        amount: 2400,\n        status: \"Paid\",\n    },\n    {\n        id: \"INV-0040\",\n        customer: \"Orbit Labs\",\n        email: \"accounts@orbit.io\",\n        date: \"Oct 03, 2026\",\n        amount: 1850,\n        status: \"Pending\",\n    },\n    {\n        id: \"INV-0039\",\n        customer: \"Northstar Inc.\",\n        email: \"finance@northstar.co\",\n        date: \"Oct 01, 2026\",\n        amount: 4200,\n        status: \"Paid\",\n    },\n    {\n        id: \"INV-0038\",\n        customer: \"Forma Design\",\n        email: \"hello@forma.design\",\n        date: \"Sep 28, 2026\",\n        amount: 960,\n        status: \"Overdue\",\n    },\n    {\n        id: \"INV-0037\",\n        customer: \"Atlas Agency\",\n        email: \"billing@atlas.co\",\n        date: \"Sep 25, 2026\",\n        amount: 3200,\n        status: \"Paid\",\n    },\n    {\n        id: \"INV-0036\",\n        customer: \"Studio Eight\",\n        email: \"hello@eight.co\",\n        date: \"Sep 22, 2026\",\n        amount: 1500,\n        status: \"Pending\",\n    },\n];\nexport function Example() {\n    return (<DemoCard title=\"Data table\" description=\"Search, sort by amount, select rows, paginate, and export CSV.\" full>\n        <DataTable rows={rows}/>\n      </DemoCard>);\n}\n",
  "Forms/Date Picker": "import { useState } from \"react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Calendar } from \"@/components/ui/calendar\";\nimport { DatePicker } from \"@/components/ui/date-picker\";\nimport { Field, FieldLabel, FieldDescription } from \"@/components/ui/field\";\nexport function Example() {\n    const [date, setDate] = useState<Date | undefined>(new Date(2026, 9, 8)), [volume, setVolume] = useState([65]), [show, setShow] = useState(false);\n    return (<DemoCard title=\"Calendar & date picker\" description=\"A consistent calendar for scheduling and invoices.\">\n        <div className=\"flex flex-wrap gap-6\">\n          <Calendar mode=\"single\" selected={date} onSelect={setDate} defaultMonth={new Date(2026, 9, 1)} className=\"border rounded-md\"/>\n          <div className=\"flex-1 min-w-40\">\n            <Field>\n              <FieldLabel htmlFor=\"showcase-date\">Selected date</FieldLabel>\n              <DatePicker id=\"showcase-date\" value={date} onChange={setDate}/>\n              <FieldDescription>\n                Click to choose a different date.\n              </FieldDescription>\n            </Field>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Overlays/Dialog": "import { useState } from \"react\";\nimport { ArrowRight } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Dialog, DialogTrigger, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter, DialogClose } from \"@/components/ui/dialog\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    const [dialog, setDialog] = useState(false), [name, setName] = useState(\"Alex Morgan\");\n    return (<DemoCard title=\"Dialog\" description=\"Focused tasks with an accessible modal and focus restoration.\">\n        <div className=\"demo-stack\">\n          <p className=\"text-sm text-muted-foreground\">\n            Edit account details in a centered dialog. Press Escape or click\n            outside to dismiss.\n          </p>\n          <Dialog open={dialog} onOpenChange={setDialog}>\n            <DialogTrigger asChild>\n              <Button>\n                Edit profile\n                <ArrowRight />\n              </Button>\n            </DialogTrigger>\n            <DialogContent>\n              <DialogHeader>\n                <DialogTitle>Edit profile</DialogTitle>\n                <DialogDescription>\n                  Make changes to your profile. Click save when you’re done.\n                </DialogDescription>\n              </DialogHeader>\n              <div className=\"demo-stack py-4\">\n                <Label htmlFor=\"profile-name\">Full name</Label>\n                <Input id=\"profile-name\" value={name} onChange={(e) => setName(e.target.value)}/>\n              </div>\n              <DialogFooter>\n                <DialogClose asChild>\n                  <Button variant=\"outline\">Cancel</Button>\n                </DialogClose>\n                <Button onClick={() => {\n            setDialog(false);\n            toast.success(\"Profile updated\", { description: name });\n        }}>\n                  Save changes\n                </Button>\n              </DialogFooter>\n            </DialogContent>\n          </Dialog>\n        </div>\n      </DemoCard>);\n}\n",
  "Overlays/Drawer": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Drawer, DrawerTrigger, DrawerContent, DrawerHeader, DrawerTitle, DrawerDescription, DrawerFooter, DrawerClose } from \"@/components/ui/drawer\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Drawer\" description=\"A touch-friendly bottom overlay powered by Vaul.\">\n        <Drawer>\n          <DrawerTrigger asChild>\n            <Button variant=\"outline\">Review monthly goal</Button>\n          </DrawerTrigger>\n          <DrawerContent>\n            <div className=\"mx-auto w-full max-w-sm\">\n              <DrawerHeader>\n                <DrawerTitle>Set your monthly goal</DrawerTitle>\n                <DrawerDescription>\n                  Give your team something to work toward.\n                </DrawerDescription>\n              </DrawerHeader>\n              <div className=\"p-4\">\n                <Label htmlFor=\"goal\">Revenue goal ($)</Label>\n                <Input id=\"goal\" type=\"number\" min=\"0\" defaultValue=\"10000\" className=\"mt-3\"/>\n              </div>\n              <DrawerFooter>\n                <DrawerClose asChild>\n                  <Button onClick={() => toast.success(\"Monthly goal updated\")}>\n                    Save goal\n                  </Button>\n                </DrawerClose>\n                <DrawerClose asChild>\n                  <Button variant=\"outline\">Cancel</Button>\n                </DrawerClose>\n              </DrawerFooter>\n            </div>\n          </DrawerContent>\n        </Drawer>\n      </DemoCard>);\n}\n",
  "Layout/Empty": "import { Plus, Inbox } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Empty, EmptyHeader, EmptyMedia, EmptyTitle, EmptyDescription, EmptyContent } from \"@/components/ui/empty\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Empty state\" description=\"A useful next step when there’s nothing to show.\">\n        <Empty className=\"border border-dashed\">\n          <EmptyHeader>\n            <EmptyMedia variant=\"icon\">\n              <Inbox />\n            </EmptyMedia>\n            <EmptyTitle>No projects yet</EmptyTitle>\n            <EmptyDescription>\n              Your next great idea needs a place to start.\n            </EmptyDescription>\n          </EmptyHeader>\n          <EmptyContent>\n            <Button onClick={() => toast.success(\"First project created\")}>\n              <Plus />\n              Create your first project\n            </Button>\n          </EmptyContent>\n        </Empty>\n      </DemoCard>);\n}\n",
  "Forms/Field": "import { useForm } from \"react-hook-form\";\nimport { zodResolver } from \"@hookform/resolvers/zod\";\nimport { z } from \"zod\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Input } from \"@/components/ui/input\";\nimport { Button } from \"@/components/ui/button\";\nimport { Form, FormField, FormItem, FormLabel, FormControl, FormMessage, FormDescription } from \"@/components/ui/form\";\nimport { toast } from \"sonner\";\nconst schema = z.object({\n    email: z.string().email(\"Please enter a valid email address.\"),\n});\nexport function Example() {\n    const form = useForm<z.infer<typeof schema>>({\n        resolver: zodResolver(schema),\n        defaultValues: { email: \"\" },\n    });\n    return (<DemoCard title=\"Validated form\" description=\"React Hook Form + Zod. Submit to see inline validation.\" full>\n        <Form {...form}>\n          <form onSubmit={form.handleSubmit((values) => toast.success(`Subscribed ${values.email}`))} className=\"flex flex-wrap items-start gap-4\">\n            <FormField control={form.control} name=\"email\" render={({ field }) => (<FormItem className=\"flex-1 min-w-52\">\n                  <FormLabel>Email address</FormLabel>\n                  <FormControl>\n                    <Input placeholder=\"you@company.com\" {...field}/>\n                  </FormControl>\n                  <FormDescription>\n                    We’ll only send useful product updates.\n                  </FormDescription>\n                  <FormMessage />\n                </FormItem>)}/>\n            <Button className=\"mt-6\" type=\"submit\">\n              Subscribe\n            </Button>\n          </form>\n        </Form>\n      </DemoCard>);\n}\n",
  "Forms/Form": "import { useForm } from \"react-hook-form\";\nimport { zodResolver } from \"@hookform/resolvers/zod\";\nimport { z } from \"zod\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Input } from \"@/components/ui/input\";\nimport { Button } from \"@/components/ui/button\";\nimport { Form, FormField, FormItem, FormLabel, FormControl, FormMessage, FormDescription } from \"@/components/ui/form\";\nimport { toast } from \"sonner\";\nconst schema = z.object({\n    email: z.string().email(\"Please enter a valid email address.\"),\n});\nexport function Example() {\n    const form = useForm<z.infer<typeof schema>>({\n        resolver: zodResolver(schema),\n        defaultValues: { email: \"\" },\n    });\n    return (<DemoCard title=\"Validated form\" description=\"React Hook Form + Zod. Submit to see inline validation.\" full>\n        <Form {...form}>\n          <form onSubmit={form.handleSubmit((values) => toast.success(`Subscribed ${values.email}`))} className=\"flex flex-wrap items-start gap-4\">\n            <FormField control={form.control} name=\"email\" render={({ field }) => (<FormItem className=\"flex-1 min-w-52\">\n                  <FormLabel>Email address</FormLabel>\n                  <FormControl>\n                    <Input placeholder=\"you@company.com\" {...field}/>\n                  </FormControl>\n                  <FormDescription>\n                    We’ll only send useful product updates.\n                  </FormDescription>\n                  <FormMessage />\n                </FormItem>)}/>\n            <Button className=\"mt-6\" type=\"submit\">\n              Subscribe\n            </Button>\n          </form>\n        </Form>\n      </DemoCard>);\n}\n",
  "Overlays/Hover Card": "import { Info } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { HoverCard, HoverCardTrigger, HoverCardContent } from \"@/components/ui/hover-card\";\nimport { Tooltip, TooltipTrigger, TooltipContent } from \"@/components/ui/tooltip\";\nimport { Avatar, AvatarFallback } from \"@/components/ui/avatar\";\nexport function Example() {\n    return (<DemoCard title=\"Hover card & tooltip\" description=\"Helpful detail, available without leaving the page.\">\n        <div className=\"demo-row\">\n          <HoverCard>\n            <HoverCardTrigger asChild>\n              <Button variant=\"link\">@alexmorgan</Button>\n            </HoverCardTrigger>\n            <HoverCardContent>\n              <div className=\"demo-row\">\n                <Avatar>\n                  <AvatarFallback>AM</AvatarFallback>\n                </Avatar>\n                <div>\n                  <h3>Alex Morgan</h3>\n                  <p className=\"text-sm text-muted-foreground\">\n                    Workspace administrator\n                  </p>\n                </div>\n              </div>\n              <p className=\"text-sm mt-3\">\n                Creating thoughtful digital experiences, one component at a\n                time.\n              </p>\n            </HoverCardContent>\n          </HoverCard>\n          {[\"top\", \"right\", \"bottom\", \"left\"].map((side) => (<Tooltip key={side}>\n              <TooltipTrigger asChild>\n                <Button variant=\"outline\" size=\"icon\" aria-label={`${side} tooltip`}>\n                  <Info />\n                </Button>\n              </TooltipTrigger>\n              <TooltipContent side={side as \"top\"}>\n                Helpful information · {side}\n              </TooltipContent>\n            </Tooltip>))}\n        </div>\n      </DemoCard>);\n}\n",
  "Forms/Input Group": "import { useState } from \"react\";\nimport { Search, Mail, Eye } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Textarea } from \"@/components/ui/textarea\";\nimport { InputGroup, InputGroupInput, InputGroupAddon, InputGroupButton } from \"@/components/ui/input-group\";\nimport { Field, FieldLabel, FieldDescription } from \"@/components/ui/field\";\nexport function Example() {\n    const [date, setDate] = useState<Date | undefined>(new Date(2026, 9, 8)), [volume, setVolume] = useState([65]), [show, setShow] = useState(false);\n    return (<DemoCard title=\"Input groups & textarea\" description=\"Composable prefixes, suffixes, and actions.\">\n        <div className=\"demo-stack\">\n          <InputGroup>\n            <InputGroupAddon>\n              <Search />\n            </InputGroupAddon>\n            <InputGroupInput aria-label=\"Search customers\" placeholder=\"Search customers...\"/>\n            <InputGroupAddon align=\"inline-end\">⌘ K</InputGroupAddon>\n          </InputGroup>\n          <InputGroup>\n            <InputGroupAddon>\n              <Mail />\n            </InputGroupAddon>\n            <InputGroupInput type=\"email\" aria-label=\"Contact email\" placeholder=\"hello@example.com\"/>\n          </InputGroup>\n          <InputGroup>\n            <InputGroupInput type={show ? \"text\" : \"password\"} aria-label=\"Password\" placeholder=\"Enter your password\"/>\n            <InputGroupAddon align=\"inline-end\">\n              <InputGroupButton aria-label=\"Show password\" onClick={() => setShow(!show)}>\n                <Eye />\n              </InputGroupButton>\n            </InputGroupAddon>\n          </InputGroup>\n          <InputGroup>\n            <InputGroupAddon>https://</InputGroupAddon>\n            <InputGroupInput aria-label=\"Domain\" placeholder=\"your-workspace\"/>\n            <InputGroupAddon align=\"inline-end\">.bluebox.app</InputGroupAddon>\n          </InputGroup>\n          <Field>\n            <FieldLabel htmlFor=\"bio\">About your business</FieldLabel>\n            <Textarea id=\"bio\" rows={4} placeholder=\"Tell us a little about what you do...\"/>\n            <FieldDescription>Keep it short and meaningful.</FieldDescription>\n          </Field>\n        </div>\n      </DemoCard>);\n}\n",
  "Forms/Input OTP": "import { useState } from \"react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Label } from \"@/components/ui/label\";\nimport { Slider } from \"@/components/ui/slider\";\nimport { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator } from \"@/components/ui/input-otp\";\nimport { Field, FieldLabel, FieldDescription } from \"@/components/ui/field\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    const [date, setDate] = useState<Date | undefined>(new Date(2026, 9, 8)), [volume, setVolume] = useState([65]), [show, setShow] = useState(false);\n    return (<DemoCard title=\"Slider & one-time password\" description=\"Fine adjustments and secure code entry.\">\n        <div className=\"demo-stack\">\n          <div>\n            <div className=\"flex justify-between mb-4\">\n              <Label>Volume</Label>\n              <span className=\"text-primary\">{volume[0]}%</span>\n            </div>\n            <Slider aria-label=\"Volume\" value={volume} onValueChange={setVolume} max={100} step={1}/>\n          </div>\n          <div>\n            <p className=\"demo-caption\">Range</p>\n            <Slider aria-label=\"Price range\" defaultValue={[20, 80]} max={100}/>\n          </div>\n          <div>\n            <p className=\"demo-caption\">Disabled</p>\n            <Slider aria-label=\"Disabled slider\" defaultValue={[40]} disabled/>\n          </div>\n          <hr />\n          <Field>\n            <FieldLabel htmlFor=\"otp\">Verification code</FieldLabel>\n            <InputOTP id=\"otp\" maxLength={6} onComplete={() => toast.success(\"Code entered successfully\")}>\n              <InputOTPGroup>\n                {[0, 1, 2].map((n) => (<InputOTPSlot index={n} key={n}/>))}\n              </InputOTPGroup>\n              <InputOTPSeparator />\n              <InputOTPGroup>\n                {[3, 4, 5].map((n) => (<InputOTPSlot index={n} key={n}/>))}\n              </InputOTPGroup>\n            </InputOTP>\n            <FieldDescription>\n              Enter the six-digit code sent to your email.\n            </FieldDescription>\n          </Field>\n        </div>\n      </DemoCard>);\n}\n",
  "Layout/Item": "import { FileText, Mail } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Avatar, AvatarFallback } from \"@/components/ui/avatar\";\nimport { Item, ItemMedia, ItemContent, ItemTitle, ItemDescription, ItemActions, ItemGroup, ItemSeparator } from \"@/components/ui/item\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Items & separators\" description=\"Reusable rows for contacts, files, and actions.\">\n        <ItemGroup>\n          <Item variant=\"outline\">\n            <ItemMedia>\n              <Avatar>\n                <AvatarFallback>AM</AvatarFallback>\n              </Avatar>\n            </ItemMedia>\n            <ItemContent>\n              <ItemTitle>Alex Morgan</ItemTitle>\n              <ItemDescription>Workspace administrator</ItemDescription>\n            </ItemContent>\n            <ItemActions>\n              <Button variant=\"ghost\" size=\"icon\" aria-label=\"Contact Alex\" onClick={() => toast(\"alex@example.com\")}>\n                <Mail />\n              </Button>\n            </ItemActions>\n          </Item>\n          <ItemSeparator />\n          <Item>\n            <ItemMedia variant=\"icon\">\n              <FileText />\n            </ItemMedia>\n            <ItemContent>\n              <ItemTitle>Design system guide</ItemTitle>\n              <ItemDescription>Updated today · Draft</ItemDescription>\n            </ItemContent>\n            <ItemActions>\n              <Button variant=\"outline\" size=\"sm\" onClick={() => {\n            toast(\"Open a component from Storybook’s sidebar\");\n        }}>\n                Open\n              </Button>\n            </ItemActions>\n          </Item>\n        </ItemGroup>\n      </DemoCard>);\n}\n",
  "Foundations/Kbd": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Separator } from \"@/components/ui/separator\";\nimport { Kbd, KbdGroup } from \"@/components/ui/kbd\";\nexport function Example() {\n    return (<DemoCard title=\"Lists & keyboard shortcuts\">\n        <ul className=\"list-disc pl-5 space-y-3 text-sm\">\n          <li>A consistent blue color palette</li>\n          <li>Accessible, functional primitives</li>\n          <li>Responsive by default</li>\n        </ul>\n        <Separator className=\"my-5\"/>\n        <div className=\"demo-row\">\n          <span>Open search</span>\n          <KbdGroup>\n            <Kbd>⌘</Kbd>\n            <Kbd>K</Kbd>\n          </KbdGroup>\n        </div>\n      </DemoCard>);\n}\n",
  "Forms/Label": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Input } from \"@/components/ui/input\";\nimport { Field, FieldLabel, FieldDescription, FieldError } from \"@/components/ui/field\";\nexport function Example() {\n    return (<DemoCard title=\"Inputs & labels\" description=\"Clear labels, subtle borders, confident focus states.\">\n        <div className=\"demo-stack\">\n          <Field>\n            <FieldLabel htmlFor=\"demo-name\">\n              Full name <span className=\"text-destructive\">*</span>\n            </FieldLabel>\n            <Input id=\"demo-name\" placeholder=\"e.g. Alex Morgan\"/>\n            <FieldDescription>\n              Your name as it appears on your account.\n            </FieldDescription>\n          </Field>\n          <Field>\n            <FieldLabel htmlFor=\"demo-error\">Email address</FieldLabel>\n            <Input id=\"demo-error\" defaultValue=\"alex@\" aria-invalid=\"true\"/>\n            <FieldError>Please enter a valid email address.</FieldError>\n          </Field>\n          <Field>\n            <FieldLabel htmlFor=\"demo-success\">Workspace URL</FieldLabel>\n            <Input id=\"demo-success\" defaultValue=\"bluebox.design\" className=\"border-[var(--success)]\"/>\n            <FieldDescription className=\"text-[var(--success)]\">\n              ✓ This URL is available.\n            </FieldDescription>\n          </Field>\n          <div className=\"grid grid-cols-2 gap-4\">\n            <Field>\n              <FieldLabel htmlFor=\"readonly\">Read only</FieldLabel>\n              <Input id=\"readonly\" value=\"INV-2026-0042\" readOnly/>\n            </Field>\n            <Field>\n              <FieldLabel htmlFor=\"disabled\">Disabled</FieldLabel>\n              <Input id=\"disabled\" value=\"Not available\" disabled/>\n            </Field>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Overlays/Popover": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Popover, PopoverTrigger, PopoverContent } from \"@/components/ui/popover\";\nexport function Example() {\n    return (<DemoCard title=\"Popover\" description=\"Lightweight settings anchored to their trigger.\">\n        <Popover>\n          <PopoverTrigger asChild>\n            <Button variant=\"outline\">Display settings</Button>\n          </PopoverTrigger>\n          <PopoverContent>\n            <h3 className=\"mb-2 text-sm\">Dimensions</h3>\n            <p className=\"text-sm text-muted-foreground mb-4\">\n              Set the dimensions for the panel.\n            </p>\n            <div className=\"grid grid-cols-2 gap-3\">\n              <Label htmlFor=\"width\">Width</Label>\n              <Input id=\"width\" defaultValue=\"100%\"/>\n              <Label htmlFor=\"height\">Height</Label>\n              <Input id=\"height\" defaultValue=\"Auto\"/>\n            </div>\n          </PopoverContent>\n        </Popover>\n      </DemoCard>);\n}\n",
  "Forms/Radio Group": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Label } from \"@/components/ui/label\";\nimport { Checkbox } from \"@/components/ui/checkbox\";\nimport { Switch } from \"@/components/ui/switch\";\nimport { RadioGroup, RadioGroupItem } from \"@/components/ui/radio-group\";\nexport function Example() {\n    return (<DemoCard title=\"Checkboxes, radios & switches\" description=\"Accessible selection controls with keyboard support.\">\n        <div className=\"demo-stack\">\n          <div className=\"demo-row\">\n            <Checkbox id=\"agree\" defaultChecked/>\n            <Label htmlFor=\"agree\">I agree to the terms and conditions</Label>\n          </div>\n          <div className=\"demo-row\">\n            <Checkbox id=\"unchecked\"/>\n            <Label htmlFor=\"unchecked\">Send me product updates</Label>\n          </div>\n          <div className=\"demo-row\">\n            <Checkbox id=\"check-disabled\" disabled/>\n            <Label htmlFor=\"check-disabled\">Unavailable option</Label>\n          </div>\n          <div className=\"demo-row\">\n            <Checkbox id=\"check-indeterminate\" checked=\"indeterminate\"/>\n            <Label htmlFor=\"check-indeterminate\">Some items selected</Label>\n          </div>\n          <hr />\n          <RadioGroup defaultValue=\"monthly\">\n            <div className=\"demo-row\">\n              <RadioGroupItem value=\"monthly\" id=\"monthly\"/>\n              <Label htmlFor=\"monthly\">Monthly billing</Label>\n            </div>\n            <div className=\"demo-row\">\n              <RadioGroupItem value=\"yearly\" id=\"yearly\"/>\n              <Label htmlFor=\"yearly\">Yearly billing · Save 20%</Label>\n            </div>\n            <div className=\"demo-row\">\n              <RadioGroupItem value=\"custom\" id=\"custom\" disabled/>\n              <Label htmlFor=\"custom\">Custom plan</Label>\n            </div>\n          </RadioGroup>\n          <hr />\n          <div className=\"flex justify-between\">\n            <Label htmlFor=\"notify\">Email notifications</Label>\n            <Switch id=\"notify\" defaultChecked/>\n          </div>\n          <div className=\"flex justify-between\">\n            <Label htmlFor=\"auto-save\">Automatically save drafts</Label>\n            <Switch id=\"auto-save\"/>\n          </div>\n          <div className=\"flex justify-between\">\n            <Label htmlFor=\"switch-disabled\">\n              Managed by your organization\n            </Label>\n            <Switch id=\"switch-disabled\" disabled/>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Layout/Separator": "import { FileText, Mail } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Avatar, AvatarFallback } from \"@/components/ui/avatar\";\nimport { Item, ItemMedia, ItemContent, ItemTitle, ItemDescription, ItemActions, ItemGroup, ItemSeparator } from \"@/components/ui/item\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Items & separators\" description=\"Reusable rows for contacts, files, and actions.\">\n        <ItemGroup>\n          <Item variant=\"outline\">\n            <ItemMedia>\n              <Avatar>\n                <AvatarFallback>AM</AvatarFallback>\n              </Avatar>\n            </ItemMedia>\n            <ItemContent>\n              <ItemTitle>Alex Morgan</ItemTitle>\n              <ItemDescription>Workspace administrator</ItemDescription>\n            </ItemContent>\n            <ItemActions>\n              <Button variant=\"ghost\" size=\"icon\" aria-label=\"Contact Alex\" onClick={() => toast(\"alex@example.com\")}>\n                <Mail />\n              </Button>\n            </ItemActions>\n          </Item>\n          <ItemSeparator />\n          <Item>\n            <ItemMedia variant=\"icon\">\n              <FileText />\n            </ItemMedia>\n            <ItemContent>\n              <ItemTitle>Design system guide</ItemTitle>\n              <ItemDescription>Updated today · Draft</ItemDescription>\n            </ItemContent>\n            <ItemActions>\n              <Button variant=\"outline\" size=\"sm\" onClick={() => {\n            toast(\"Open a component from Storybook’s sidebar\");\n        }}>\n                Open\n              </Button>\n            </ItemActions>\n          </Item>\n        </ItemGroup>\n      </DemoCard>);\n}\n",
  "Overlays/Sheet": "import { Bell } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { Sheet, SheetTrigger, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter, SheetClose } from \"@/components/ui/sheet\";\nexport function Example() {\n    return (<DemoCard title=\"Sheet\" description=\"A side panel for secondary details and navigation.\">\n        <Sheet>\n          <SheetTrigger asChild>\n            <Button variant=\"outline\">\n              <Bell />\n              Open notifications\n            </Button>\n          </SheetTrigger>\n          <SheetContent>\n            <SheetHeader>\n              <SheetTitle>Notifications</SheetTitle>\n              <SheetDescription>\n                You’re all caught up on the important things.\n              </SheetDescription>\n            </SheetHeader>\n            <div className=\"p-6 demo-stack\">\n              <div className=\"p-4 rounded-md bg-accent\">\n                <strong className=\"text-sm\">Design system ready</strong>\n                <p className=\"text-sm text-muted-foreground mt-2\">\n                  Your themed components are ready to explore.\n                </p>\n              </div>\n              <div className=\"p-4 rounded-md bg-muted\">\n                <strong className=\"text-sm\">Invoice draft created</strong>\n                <p className=\"text-sm text-muted-foreground mt-2\">\n                  Continue editing INV-2026-0042.\n                </p>\n              </div>\n            </div>\n            <SheetFooter>\n              <SheetClose asChild>\n                <Button>Mark as read</Button>\n              </SheetClose>\n            </SheetFooter>\n          </SheetContent>\n        </Sheet>\n      </DemoCard>);\n}\n",
  "Feedback/Skeleton": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Skeleton } from \"@/components/ui/skeleton\";\nimport { Spinner } from \"@/components/ui/spinner\";\nexport function Example() {\n    return (<DemoCard title=\"Skeleton & spinner\" description=\"Calm loading placeholders that preserve layout.\">\n        <div className=\"demo-stack\">\n          <div className=\"flex gap-4\">\n            <Skeleton className=\"size-10 rounded-full\"/>\n            <div className=\"space-y-2 flex-1\">\n              <Skeleton className=\"h-3 w-3/4\"/>\n              <Skeleton className=\"h-3 w-1/2\"/>\n            </div>\n          </div>\n          <Skeleton className=\"h-24 w-full\"/>\n          <div className=\"demo-row\">\n            <Spinner />\n            <span className=\"text-sm text-muted-foreground\">\n              Loading your workspace...\n            </span>\n            <Spinner className=\"size-6 text-primary\"/>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Feedback/Sonner": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { toast } from \"sonner\";\nexport function Example() {\n    return (<DemoCard title=\"Toast notifications\" description=\"Sonner feedback with accessible, dismissible messages.\" full>\n        <div className=\"demo-row\">\n          <Button variant=\"outline\" onClick={() => toast(\"Your changes have been saved\")}>\n            Default\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast.success(\"Invoice saved successfully\")}>\n            Success\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast.warning(\"Your payment is due soon\")}>\n            Warning\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast.error(\"Please check your email address\")}>\n            Error\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast.info(\"You have two new notifications\")}>\n            Info\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast(\"Invoice archived\", {\n            action: {\n                label: \"Undo\",\n                onClick: () => toast.success(\"Invoice restored\"),\n            },\n        })}>\n            With action\n          </Button>\n          <Button variant=\"outline\" onClick={() => toast.promise(new Promise((resolve) => setTimeout(resolve, 1500)), {\n            loading: \"Preparing export...\",\n            success: \"Export ready\",\n            error: \"Export failed\",\n        })}>\n            Promise\n          </Button>\n        </div>\n      </DemoCard>);\n}\n",
  "Feedback/Spinner": "import { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Skeleton } from \"@/components/ui/skeleton\";\nimport { Spinner } from \"@/components/ui/spinner\";\nexport function Example() {\n    return (<DemoCard title=\"Skeleton & spinner\" description=\"Calm loading placeholders that preserve layout.\">\n        <div className=\"demo-stack\">\n          <div className=\"flex gap-4\">\n            <Skeleton className=\"size-10 rounded-full\"/>\n            <div className=\"space-y-2 flex-1\">\n              <Skeleton className=\"h-3 w-3/4\"/>\n              <Skeleton className=\"h-3 w-1/2\"/>\n            </div>\n          </div>\n          <Skeleton className=\"h-24 w-full\"/>\n          <div className=\"demo-row\">\n            <Spinner />\n            <span className=\"text-sm text-muted-foreground\">\n              Loading your workspace...\n            </span>\n            <Spinner className=\"size-6 text-primary\"/>\n          </div>\n        </div>\n      </DemoCard>);\n}\n",
  "Actions/Toggle Group": "import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Toggle } from \"@/components/ui/toggle\";\nimport { ToggleGroup, ToggleGroupItem } from \"@/components/ui/toggle-group\";\nexport function Example() {\n    return (<DemoCard title=\"Toggle & toggle group\" description=\"Pressed states for formatting and view controls.\">\n        <div className=\"demo-stack\">\n          <div className=\"demo-row\">\n            <Toggle aria-label=\"Bold\">\n              <Bold />\n            </Toggle>\n            <Toggle aria-label=\"Italic\" variant=\"outline\">\n              <Italic />\n            </Toggle>\n            <Toggle aria-label=\"Underline\" disabled>\n              <Underline />\n            </Toggle>\n          </div>\n          <ToggleGroup type=\"single\" defaultValue=\"left\" variant=\"outline\">\n            <ToggleGroupItem value=\"left\" aria-label=\"Align left\">\n              <AlignLeft />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"center\" aria-label=\"Align center\">\n              <AlignCenter />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"right\" aria-label=\"Align right\">\n              <AlignRight />\n            </ToggleGroupItem>\n          </ToggleGroup>\n          <ToggleGroup type=\"multiple\" defaultValue={[\"bold\"]}>\n            <ToggleGroupItem value=\"bold\" aria-label=\"Bold format\">\n              <Bold />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"italic\" aria-label=\"Italic format\">\n              <Italic />\n            </ToggleGroupItem>\n          </ToggleGroup>\n        </div>\n      </DemoCard>);\n}\n",
  "Actions/Toggle": "import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Toggle } from \"@/components/ui/toggle\";\nimport { ToggleGroup, ToggleGroupItem } from \"@/components/ui/toggle-group\";\nexport function Example() {\n    return (<DemoCard title=\"Toggle & toggle group\" description=\"Pressed states for formatting and view controls.\">\n        <div className=\"demo-stack\">\n          <div className=\"demo-row\">\n            <Toggle aria-label=\"Bold\">\n              <Bold />\n            </Toggle>\n            <Toggle aria-label=\"Italic\" variant=\"outline\">\n              <Italic />\n            </Toggle>\n            <Toggle aria-label=\"Underline\" disabled>\n              <Underline />\n            </Toggle>\n          </div>\n          <ToggleGroup type=\"single\" defaultValue=\"left\" variant=\"outline\">\n            <ToggleGroupItem value=\"left\" aria-label=\"Align left\">\n              <AlignLeft />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"center\" aria-label=\"Align center\">\n              <AlignCenter />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"right\" aria-label=\"Align right\">\n              <AlignRight />\n            </ToggleGroupItem>\n          </ToggleGroup>\n          <ToggleGroup type=\"multiple\" defaultValue={[\"bold\"]}>\n            <ToggleGroupItem value=\"bold\" aria-label=\"Bold format\">\n              <Bold />\n            </ToggleGroupItem>\n            <ToggleGroupItem value=\"italic\" aria-label=\"Italic format\">\n              <Italic />\n            </ToggleGroupItem>\n          </ToggleGroup>\n        </div>\n      </DemoCard>);\n}\n",
  "Overlays/Tooltip": "import { Info } from \"lucide-react\";\nimport { DemoCard } from \"@/components/showcase/demo-card\";\nimport { Button } from \"@/components/ui/button\";\nimport { HoverCard, HoverCardTrigger, HoverCardContent } from \"@/components/ui/hover-card\";\nimport { Tooltip, TooltipTrigger, TooltipContent } from \"@/components/ui/tooltip\";\nimport { Avatar, AvatarFallback } from \"@/components/ui/avatar\";\nexport function Example() {\n    return (<DemoCard title=\"Hover card & tooltip\" description=\"Helpful detail, available without leaving the page.\">\n        <div className=\"demo-row\">\n          <HoverCard>\n            <HoverCardTrigger asChild>\n              <Button variant=\"link\">@alexmorgan</Button>\n            </HoverCardTrigger>\n            <HoverCardContent>\n              <div className=\"demo-row\">\n                <Avatar>\n                  <AvatarFallback>AM</AvatarFallback>\n                </Avatar>\n                <div>\n                  <h3>Alex Morgan</h3>\n                  <p className=\"text-sm text-muted-foreground\">\n                    Workspace administrator\n                  </p>\n                </div>\n              </div>\n              <p className=\"text-sm mt-3\">\n                Creating thoughtful digital experiences, one component at a\n                time.\n              </p>\n            </HoverCardContent>\n          </HoverCard>\n          {[\"top\", \"right\", \"bottom\", \"left\"].map((side) => (<Tooltip key={side}>\n              <TooltipTrigger asChild>\n                <Button variant=\"outline\" size=\"icon\" aria-label={`${side} tooltip`}>\n                  <Info />\n                </Button>\n              </TooltipTrigger>\n              <TooltipContent side={side as \"top\"}>\n                Helpful information · {side}\n              </TooltipContent>\n            </Tooltip>))}\n        </div>\n      </DemoCard>);\n}\n"
};
